require_once __DIR__.'/../includes/bootstrap.php';$id=(int)($_GET['id']??0);$p=db_one('SELECT p.*,d.department_name FROM procurement_ppmp p LEFT JOIN departments d ON d.id=p.department_id WHERE p.id=?',[$id]);if(!$p)exit('PPMP not found.');
if(isset($_GET['review_comment'])){
    header('Content-Type: application/json; charset=utf-8');
    $comments=db_all('SELECT id,ppmp_item_id item_id,review_field,comment,follow_up_comments,resolution_status,reviewed_by FROM procurement_ppmp_review_comments WHERE ppmp_id=? ORDER BY ppmp_item_id,review_field',[$id]);foreach($comments as&$reviewComment){$reviewComment['follow_ups']=json_decode((string)($reviewComment['follow_up_comments']??''),true)?:[];unset($reviewComment['follow_up_comments']);}unset($reviewComment);
    $hasBaseline=(int)db_value('SELECT COUNT(*) FROM procurement_ppmp_revision_baselines WHERE ppmp_id=?',[$id])>0;
    $changes=$hasBaseline?db_all('SELECT pi.id item_id,CASE WHEN b.item_id IS NULL THEN "ADDED" ELSE "UPDATED" END change_type,b.planned_quantity previous_quantity,pi.planned_quantity current_quantity,b.unit_cost previous_unit_cost,pi.unit_cost current_unit_cost FROM procurement_ppmp_items pi LEFT JOIN procurement_ppmp_revision_baselines b ON b.ppmp_id=pi.ppmp_id AND b.item_id=pi.item_id WHERE pi.ppmp_id=? AND (b.item_id IS NULL OR b.planned_quantity<>pi.planned_quantity OR b.unit_cost<>pi.unit_cost OR b.item_description<>pi.item_description)',[$id]):db_all('SELECT DISTINCT pi.id item_id,"REVISED" change_type,NULL previous_quantity,pi.planned_quantity current_quantity,NULL previous_unit_cost,pi.unit_cost current_unit_cost FROM procurement_ppmp_items pi JOIN procurement_ppmp_review_comments c ON c.ppmp_item_id=pi.id WHERE pi.ppmp_id=? AND ?="FOR APPROVAL"',[$id,$p['status']]);
    $removed=$hasBaseline?db_all('SELECT b.item_description,b.planned_quantity,b.unit_cost FROM procurement_ppmp_revision_baselines b LEFT JOIN procurement_ppmp_items pi ON pi.ppmp_id=b.ppmp_id AND pi.item_id=b.item_id WHERE b.ppmp_id=? AND pi.id IS NULL',[$id]):[];
    $generalComment=db_one('SELECT comment,follow_up_comments,resolution_status,reviewed_by FROM procurement_ppmp_general_comments WHERE ppmp_id=? AND resolution_status<>"RESOLVED"',[$id]);if($generalComment){$generalComment['follow_ups']=json_decode((string)($generalComment['follow_up_comments']??''),true)?:[];unset($generalComment['follow_up_comments']);}
    echo json_encode(['comments'=>$comments,'general_comment'=>$generalComment,'changes'=>$changes,'removed_items'=>$removed,'status'=>$p['status'],'revision_round'=>(int)($p['revision_round']??0),'show_review_status'=>in_array($p['status'],['FOR REVISION','FOR APPROVAL'],true)&&(int)($p['revision_round']??0)>0,'can_edit'=>can_approve_ppmp()&&$p['status']==='FOR APPROVAL','csrf_token'=>csrf_token()]);exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
    header('Content-Type: application/json; charset=utf-8');
    if(!can_approve_ppmp()||$p['status']!=='FOR APPROVAL'){http_response_code(403);echo json_encode(['error'=>'Comments can only be changed while the PPMP is for approval.']);exit;}
    verify_csrf_token();
    if(($_POST['review_action']??'')==='delete_general_follow_up'){
        $existing=db_one('SELECT id,follow_up_comments FROM procurement_ppmp_general_comments WHERE ppmp_id=?',[$id]);$index=(int)($_POST['follow_up_index']??-1);$history=$existing?(json_decode((string)($existing['follow_up_comments']??''),true)?:[]):[];if(!$existing||!array_key_exists($index,$history)){http_response_code(422);echo json_encode(['error'=>'Follow-up comment not found.']);exit;}if((int)($history[$index]['revision_round']??-1)!==(int)($p['revision_round']??0)){http_response_code(409);echo json_encode(['error'=>'Previous follow-up comments cannot be deleted.']);exit;}array_splice($history,$index,1);db_statement('UPDATE procurement_ppmp_general_comments SET follow_up_comments=?,reviewed_by=? WHERE id=?',[json_encode($history,JSON_UNESCAPED_UNICODE),current_user()['full_name'],$existing['id']]);echo json_encode(['ok'=>true]);exit;
    }
    if(($_POST['review_action']??'')==='save_general'){
        $comment=trim((string)($_POST['review_comment']??''));$followUp=trim((string)($_POST['follow_up_comment']??''));$existing=db_one('SELECT * FROM procurement_ppmp_general_comments WHERE ppmp_id=?',[$id]);
        if($existing&&$existing['resolution_status']==='RESOLVED'&&$comment!=='')db_statement('UPDATE procurement_ppmp_general_comments SET comment=?,follow_up_comments=NULL,resolution_status="PENDING REVISION",reviewed_by=? WHERE id=?',[$comment,current_user()['full_name'],$existing['id']]);
        elseif($existing&&$followUp!==''){$history=json_decode((string)($existing['follow_up_comments']??''),true)?:[];$history[]=['comment'=>$followUp,'reviewed_by'=>current_user()['full_name'],'created_at'=>date('Y-m-d H:i:s'),'revision_round'=>(int)($p['revision_round']??0)];$nextStatus=$existing['resolution_status']==='REVISED'?'NEEDS FURTHER REVISION':$existing['resolution_status'];db_statement('UPDATE procurement_ppmp_general_comments SET follow_up_comments=?,resolution_status=?,reviewed_by=? WHERE id=?',[json_encode($history,JSON_UNESCAPED_UNICODE),$nextStatus,current_user()['full_name'],$existing['id']]);}
        elseif(!$existing&&$comment!=='')db_statement('INSERT INTO procurement_ppmp_general_comments(ppmp_id,comment,reviewed_by) VALUES(?,?,?)',[$id,$comment,current_user()['full_name']]);
        else{http_response_code(422);echo json_encode(['error'=>$existing?'Add a follow-up after the general comment is revised.':'Enter a general comment.']);exit;}
        echo json_encode(['ok'=>true]);exit;
    }
    $comment=trim((string)($_POST['review_comment']??''));$followUp=trim((string)($_POST['follow_up_comment']??''));$itemId=(int)($_POST['ppmp_item_id']??0);$field=strtoupper(trim((string)($_POST['review_field']??'GENERAL')));$status='PENDING REVISION';
    if(!db_one('SELECT id FROM procurement_ppmp_items WHERE id=? AND ppmp_id=?',[$itemId,$id])){http_response_code(422);echo json_encode(['error'=>'The selected PPMP row was not found.']);exit;}
    if(($_POST['review_action']??'')==='resolve_item'){
        db_statement('UPDATE procurement_ppmp_review_comments SET resolution_status="RESOLVED",reviewed_by=? WHERE ppmp_id=? AND ppmp_item_id=? AND resolution_status="REVISED"',[current_user()['full_name'],$id,$itemId]);
        echo json_encode(['ok'=>true,'item_id'=>$itemId]);exit;
    }
    if(!in_array($field,['QUANTITY','UNIT PRICE'],true)){http_response_code(422);echo json_encode(['error'=>'Item comments can only target Quantity or Unit Price.']);exit;}
    $locked=(int)($p['revision_round']??0)>0;$existingComment=db_one('SELECT * FROM procurement_ppmp_review_comments WHERE ppmp_id=? AND ppmp_item_id=? AND review_field=?',[$id,$itemId,$field]);
    if(($_POST['review_action']??'')==='delete_follow_up'){$index=(int)($_POST['follow_up_index']??-1);$history=$existingComment?(json_decode((string)($existingComment['follow_up_comments']??''),true)?:[]):[];if(!$existingComment||!array_key_exists($index,$history)){http_response_code(422);echo json_encode(['error'=>'Follow-up comment not found.']);exit;}if((int)($history[$index]['revision_round']??-1)!==(int)($p['revision_round']??0)){http_response_code(409);echo json_encode(['error'=>'Previous follow-up comments cannot be deleted.']);exit;}array_splice($history,$index,1);db_statement('UPDATE procurement_ppmp_review_comments SET follow_up_comments=?,reviewed_by=? WHERE id=?',[json_encode($history,JSON_UNESCAPED_UNICODE),current_user()['full_name'],$existingComment['id']]);echo json_encode(['ok'=>true]);exit;}
    if($locked&&(isset($_POST['delete_all'])||($comment===''&&$followUp===''))){http_response_code(409);echo json_encode(['error'=>'Previous reviewer comments cannot be deleted after resubmission.']);exit;}
    if(isset($_POST['delete_all']))db_statement('DELETE FROM procurement_ppmp_review_comments WHERE ppmp_id=? AND ppmp_item_id=?',[$id,$itemId]);
    elseif($comment==='')db_statement('DELETE FROM procurement_ppmp_review_comments WHERE ppmp_id=? AND ppmp_item_id=? AND review_field=?',[$id,$itemId,$field]);
    elseif($existingComment&&$followUp!==''){$followUps=json_decode((string)($existingComment['follow_up_comments']??''),true)?:[];$followUps[]=['comment'=>$followUp,'reviewed_by'=>current_user()['full_name'],'created_at'=>date('Y-m-d H:i:s'),'revision_round'=>(int)($p['revision_round']??0)];$nextStatus=$existingComment['resolution_status']==='REVISED'?'NEEDS FURTHER REVISION':$existingComment['resolution_status'];db_statement('UPDATE procurement_ppmp_review_comments SET follow_up_comments=?,resolution_status=?,reviewed_by=? WHERE id=?',[json_encode($followUps,JSON_UNESCAPED_UNICODE),$nextStatus,current_user()['full_name'],$existingComment['id']]);}
    elseif($locked&&$existingComment){}
    else db_statement('INSERT INTO procurement_ppmp_review_comments(ppmp_id,ppmp_item_id,review_field,comment,resolution_status,reviewed_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE comment=VALUES(comment),resolution_status=VALUES(resolution_status),reviewed_by=VALUES(reviewed_by)',[$id,$itemId,$field,$comment,$status,current_user()['full_name']]);
    $savedComment=db_one('SELECT ppmp_item_id item_id,review_field,comment,follow_up_comments,resolution_status,reviewed_by FROM procurement_ppmp_review_comments WHERE ppmp_id=? AND ppmp_item_id=? AND review_field=?',[$id,$itemId,$field]);if($savedComment){$savedComment['follow_ups']=json_decode((string)($savedComment['follow_up_comments']??''),true)?:[];unset($savedComment['follow_up_comments']);}echo json_encode(['ok'=>true]+($savedComment?:['item_id'=>$itemId,'review_field'=>$field,'comment'=>'','follow_ups'=>[],'resolution_status'=>$status,'reviewed_by'=>current_user()['full_name']]));exit;
}
$items=db_all('SELECT * FROM procurement_ppmp_items WHERE ppmp_id=? ORDER BY id',[$id]);
$preparedDesignation='';
if(strcasecmp(trim((string)($p['department_name']??'')),'CSSR')!==0){
    $preparer=db_one('SELECT username FROM users WHERE id=?',[(int)($p['created_by']??0)]);
    $preparerProfile=$preparer?shared_one('SELECT * FROM users WHERE username=? LIMIT 1',[$preparer['username']]):null;
    $position=trim((string)($preparerProfile['position']??''));
    $departmentName=trim((string)($p['department_name']??''));
    $preparedDesignation=implode(' - ',array_filter([$position,$departmentName],static fn($value)=>$value!==''));
}
